// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    X_WALLET c;

    function setUp() public {
        c = new X_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 unlockTime) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // Admissible domain: nonzero deposit that reaches MinSum, nonzero collect not exceeding deposit,
        // and an unlock time far enough in the future that Collect's time gate passes.
        depositAmount = bound(depositAmount, c.MinSum(), 1e30);
        collectAmount = bound(collectAmount, 1, depositAmount);
        unlockTime = bound(unlockTime, 1, 365 days);

        address actor = address(0xBEEF);
        vm.deal(actor, depositAmount);

        vm.prank(actor);
        c.Put{value: depositAmount}(unlockTime);

        (uint256 beforeUnlock, uint256 beforeBalance) = c.Acc(actor);

        vm.warp(beforeUnlock + 1);

        vm.prank(actor);
        c.Collect(collectAmount);

        (uint256 afterUnlock, uint256 afterBalance) = c.Acc(actor);

        uint256 decrease = beforeBalance - afterBalance;
        assertTrue(decrease == collectAmount);
    }
}
